import { lazy, Suspense,useState } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import NavBar from "./components/Navbar/Navbar";
import Footer from "./components/Footer/Footer";
import Loader from "./components/Loader/Loader";
import { ToastContainer } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import Profile from './pages/Profile';
import Landing from './pages/Landing';

const Home = lazy(() => import("./pages/Home"));
const Shop = lazy(() => import("./pages/Shop"));
const Cart = lazy(() => import("./pages/Cart"));
const Product = lazy(() => import("./pages/Product"));
// Create a wrapper component that uses useLocation
const AppContent = (isGitHub) => {
  const location = useLocation();
 // State to track the mode (Simple or Gamification)

  const isGithubPages = window.location.href.includes('/my_eco');
  const basename = isGithubPages ? '/my_eco' : '';
  const setMode = (flag) => {
    if(flag) {
      localStorage.setItem('appVersion','gamification')
    } else {
      localStorage.setItem('appVersion','simple')
    }
    window.location.reload()
  }
  // Check if we're at the root path relative to the basename
  const isLandingPage = location.pathname === basename || location.pathname === `${basename}/`;
  let isGame = localStorage.getItem('appVersion') === "gamification";

  console.log({
    pathname: location.pathname,
    basename,
    isLandingPage,
    fullUrl: window.location.href
  });
  return (
    <>
      {!isLandingPage && <NavBar mode={isGame} setMode={setMode} />}
      <Routes>
        <Route path="/" element={<Landing />} />
        <Route path="/home" element={<Home />} />
        <Route path="/shop" element={<Shop />} />
        <Route path="/shop/:id" element={<Product />} />
        <Route path="/cart" element={<Cart />} />
        <Route path="/profile" element={<Profile />} />
      </Routes>
      {!isLandingPage && isGame && <Footer />}
    </>
  );
};

function App() {

  // Determine if we're on GitHub Pages
  const isGithubPages = window.location.href.includes('.io/my_eco');
  // Set the basename accordingly
  const basename = isGithubPages ? '/my_eco' : '';

  return (
    <Router basename={basename}>
      <Suspense fallback={<Loader />}>
        <ToastContainer
          position="top-right"
          autoClose={1000}
          hideProgressBar={false}
          newestOnTop={false}
          closeOnClick
          pauseOnFocusLoss
          draggable
          pauseOnHover
          theme="light"
        />
        <AppContent isGitHub={isGithubPages}/>
      </Suspense>
    </Router>
  );
}


export default App;
