import React, { useState } from 'react';
import { Modal, Button, Form, Alert } from 'react-bootstrap';
import { useDispatch, useSelector } from 'react-redux';
import { loginSuccess, loginFail, signupSuccess, signupFail } from '../../app/features/authSlice';
import './auth-modal.css';
import { ENDPOINTS } from '../../app/config/config.js';


const AuthModal = ({ show, handleClose }) => {
    const [isLogin, setIsLogin] = useState(true);
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const dispatch = useDispatch();
    const error = useSelector(state => state.auth.error);

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (isLogin) {
            if (username && password) {
                try {
                    const response = await fetch(ENDPOINTS.LOGIN, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify({ username, password }),
                    });

                    if (!response.ok) {
                        throw new Error('Login failed');
                    }

                    dispatch(loginSuccess({ username }));
                    handleClose();
                    localStorage.setItem("username", username)
                    setUsername(username);
                    setPassword(password);
                } catch (error) {
                    dispatch(loginFail('Invalid credentials'));
                }
            }
        } else {
            if (username && password) {
                try {

                    const response = await fetch(ENDPOINTS.SIGNUP, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify({ username, password }),
                    });

                    if (!response.ok) {
                        throw new Error('Signup failed');
                    }

                    dispatch(signupSuccess({ username }));
                    handleClose();
                    setUsername(username);
                    setPassword(password);
                } catch (error) {
                    dispatch(signupFail('Signup failed'));
                }
            }
        }
    };

    return (
        <Modal show={show} onHide={handleClose} centered className="auth-modal">
            <Modal.Header closeButton>
                <Modal.Title>{isLogin ? 'Login' : 'Sign Up'}</Modal.Title>
            </Modal.Header>
            <Modal.Body>
                {error && <Alert variant="danger">{error}</Alert>}
                <Form onSubmit={handleSubmit}>
                    <Form.Group className="mb-3">
                        <Form.Label>Username</Form.Label>
                        <Form.Control
                            type="text"
                            placeholder="Enter username"
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            required
                        />
                    </Form.Group>

                    <Form.Group className="mb-3">
                        <Form.Label>Password</Form.Label>
                        <Form.Control
                            type="password"
                            placeholder="Password"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            required
                        />
                    </Form.Group>

                    <Button variant="primary" type="submit" className="w-100 mb-3">
                        {isLogin ? 'Login' : 'Sign Up'}
                    </Button>
                </Form>
                <div className="text-center">
                    <Button
                        variant="link"
                        onClick={() => setIsLogin(!isLogin)}
                        className="switch-auth-mode"
                    >
                        {isLogin ? "Don't have an account? Sign Up" : "Already have an account? Login"}
                    </Button>
                </div>
            </Modal.Body>
        </Modal>
    );
};

export default AuthModal; 