import { createSlice } from '@reduxjs/toolkit';

const initialState = {
    reviews: 0,
    discount: 0,
    avg_rating: 0
  };
  
  const calculateDiscount = (reviews) => {
    return Math.min((reviews / 10) * 5, 15);
  };
  
  const reviewsSlice = createSlice({
    name: "reviews",
    initialState,
    reducers: {
      addReview: (state) => {
        state.reviews += 1;
        state.discount = calculateDiscount(state.reviews);
      },
      removeReview: (state) => {
        if (state.reviews > 0) {
          state.reviews -= 1;
          state.discount = calculateDiscount(state.reviews);
        }
      },
      setReviews: (state, action) => {
        state.reviews = action.payload.reviews;
        state.discount = calculateDiscount(state.reviews);
        state.avg_rating = action.payload.avg;
      },
      resetReviews: (state) => {
        state.reviews = 0;
        state.discount = 0;
        state.avg_rating = 0;
      },
    },
  });
  
  export const { addReview, removeReview, setReviews, resetReviews } = reviewsSlice.actions;
  export default reviewsSlice.reducer;