import React from 'react';

const Switch = ({ currentMode, onSwitchChange }) => {
  const toggleSwitch = () => {
    // Toggle the state and pass the new mode to the parent
    const newMode = currentMode ? false : true;

    onSwitchChange(newMode);
  };

  return (
    <div>
      <label style={{ display: "flex", alignItems: "center", marginBottom: "10px" }}>
        <span style={{ marginRight: "10px" }}>{currentMode ? 'Gamification' : 'Simple'}</span>
        <input 
          type="checkbox" 
          checked={currentMode === true} // Checked if the current mode is 'Gamification'
          onChange={toggleSwitch} 
          style={{ transform: "scale(1.5)" }} // Increase size of the switch
        />
      </label>
    </div>
  );
};

export default Switch;
