import { useState, useEffect } from "react";
import { Container, Row, Col, Card } from "react-bootstrap";
import { useAuth,useDiscount } from "../hooks/useAuth";
import { useDispatch } from "react-redux";
import { logout } from "../app/features/authSlice";
import { useNavigate } from "react-router-dom";
import { ENDPOINTS } from '../app/config/config.js';
import trackEvent from "../utils/trackEvent.js";
import freeShipper from "../Images/freeShipper.png";
import handReview from "../Images/handReview.png";
import reviewer from "../Images/reviewer.png";
import "./profile.css";

const Profile = () => {
  const discounts = useDiscount();
  const { user } = useAuth();
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [userStats, setUserStats] = useState({
    totalReviews: 0,
    averageRating: 0,
    totalPurchases: 0,
  });
  const [loading, setLoading] = useState(true);
  trackEvent("navigated_to_profile")

  const getBadges = () => {
    const badges = [];
    
    // Review badges
    if (discounts.reviews >= 25) {
      badges.push({ name: "Review Master", icon: reviewer, description: "Έκανες 25+ αξιολογήσεις" });
    } else if (discounts.reviews >= 15) {
      badges.push({ name: "Ενεργός Reviewer", icon: reviewer, description: "Έκανες 15+ αξιολογήσεις" });
    } else if (discounts.reviews >= 5) {
      badges.push({ name: "Αρχάριος Reviewer", icon: reviewer, description: "Έκανες 5+ αξιολογήσεις" });
    }

    // Rating badges
    if (userStats.averageRating >= 4.2) {
      badges.push({ name: "Ποιοτικός Αξιολογητής", icon: freeShipper, description: "High-quality αξιολογήσεις" });
      localStorage.setItem("freeShipper", "earned")
    }

    // Purchase badges
    if (userStats.totalPurchases >= 10) {
      badges.push({ name: "Πιστός Πελάτης", icon: handReview, description: "Έκανες 10+ αγορές" });
    }

    return badges;
  };

  const handleLogout = () => {
    trackEvent("user_logout")
    dispatch(logout());
    navigate("/");
  };



  return (
    <Container className="profile-container">
      <Row>
        {/* User Info Card */}
        <Col md={4}>
          <Card className="profile-card">
            <div className="profile-header">
              <div className="profile-avatar">
                {user.username.charAt(0).toUpperCase()}
              </div>
              <h2>{user.username}</h2>
              <p className="member-since">Member since {new Date(user.createdAt).toLocaleDateString()}</p>
            </div>
            <button onClick={handleLogout} className="logout-btn">
              Αποσύνδεση
            </button>
          </Card>
        </Col>

        {/* Stats Card */}
        <Col md={8}>
          <Card className="stats-card">
            <h3>Η Δραστηριότητα σου</h3>
            <div className="stats-grid">
              <div className="stat-item">
                <span className="stat-value">{discounts.reviews}</span>
                <span className="stat-label">Αξιολογήσεις</span>
              </div>
              <div className="stat-item">
                <span className="stat-value">{discounts.avg_rating.toFixed(1)}</span>
                <span className="stat-label">Μ/Ο Αξιολόγησης</span>
              </div>
              <div className="stat-item">
                <span className="stat-value">{userStats.totalPurchases}</span>
                <span className="stat-label">Αγορές</span>
              </div>
            </div>
          </Card>

          {/* Badges Card */}
          <Card className="badges-card">
            <h3>Τα Badges σου</h3>
            <div className="badges-grid">
              {getBadges().map((badge, index) => (
                <div key={index} className="badge-item">
                  <span className="badge-icon">
                  <img loading="lazy" src={badge.icon} alt="" /></span>
                  <div className="badge-name">{badge.name}</div>
                  <div className="badge-description">{badge.description}</div>
                </div>
              ))}
              {getBadges().length === 0 && (
                <p className="no-badges">Δεν εχεις κερδίσει ακομα κανένα badge!</p>
              )}
            </div>
          </Card>
        </Col>
        <Card className="profile-card-col">
            <div  className="badge-item-col">
                  <span className="badge-icon">
                  <img loading="lazy" src={handReview} alt="" /></span>
                  <div className="badge-name">{"🛍️ Loyalty Shopper Badge"}</div>
                  <div className="badge-description">{`Μετά από 5 αγορές, κερδίζετε αυτόματα 5% έκπτωση στις επόμενες παραγγελίες σας!\nΣυνεχίστε να ψωνίζετε και κερδίστε ακόμα περισσότερα!"`}</div>
                  <div className="badge-description">{"(Η προσφορά απαιτεί 5 επιβεβαιωμένες αγορές)"}</div>
                </div>
                <div  className="badge-item-col">
                <span className="badge-icon">
                  <img loading="lazy" src={freeShipper} alt="" /></span>
                  <div className="badge-name">{"🌟 Exclusive Insider Badge"}</div>
                  <div className="badge-description">{"Είσαι VIP! ⭐ Αφήνοντας 10 verified ratings σε προϊόντα, γίνεσαι Exclusive Insider και αποκτάς πρόσβαση σε μυστικές προσφορές και αποκλειστικά deals μέσω email!"}</div>
                  <div className="badge-description">{"(Η προσφορά απαιτεί χρονική χρήση τουλάχιστον 1 μήνα)"}</div>
                </div>
                <div  className="badge-item-col">
                <span className="badge-icon">
                  <img loading="lazy" src={reviewer} alt="" /></span>
                  <div className="badge-name">{"📦 Review & Save Badge"}</div>
                  <div className="badge-description">{"Η γνώμη σας μετράει! 📝 Αφήστε 10 verified σχόλια σε προϊόντα που έχετε αγοράσει και κερδίστε δωρεάν μεταφορικά στην επόμενη παραγγελία σας!"}</div>
                  <div className="badge-description">{"(Η προσφορά απαιτεί χρονική χρήση τουλάχιστον 1 μήνα)"}</div>

                </div>
          </Card>
      </Row>
    </Container>
  );
};

export default Profile;